-- Profil fotograflari icin ozel depo
INSERT INTO storage.buckets (id, name, public) VALUES ('avatars','avatars',false) ON CONFLICT (id) DO NOTHING;

-- ---------- 0000_real_multiplayer_accounts.sql ----------
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL UNIQUE CHECK (char_length(username) BETWEEN 3 AND 30), display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 40), avatar_url text NOT NULL DEFAULT '', frame text NOT NULL DEFAULT '', stone text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE (display_name, avatar_url, frame, stone) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (true);
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.wallets (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, tokens bigint NOT NULL DEFAULT 0 CHECK(tokens>=0), hearts bigint NOT NULL DEFAULT 0 CHECK(hearts>=0), kisses bigint NOT NULL DEFAULT 0, gestures bigint NOT NULL DEFAULT 0, vip boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.wallets TO authenticated; GRANT ALL ON public.wallets TO service_role;
ALTER TABLE public.wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_own ON public.wallets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,username,display_name) VALUES(NEW.id, 'u_'||replace(NEW.id::text,'-',''), left(coalesce(nullif(NEW.raw_user_meta_data->>'display_name',''),nullif(NEW.raw_user_meta_data->>'full_name',''),'Oyuncu'),40)); INSERT INTO public.wallets(user_id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER create_player_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE TABLE public.game_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT 'Şişe Masası', round jsonb NOT NULL DEFAULT '{"phase":"offer","spinner":null,"target":null,"decisions":{}}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_rooms TO authenticated; GRANT ALL ON public.game_rooms TO service_role;
ALTER TABLE public.game_rooms ENABLE ROW LEVEL SECURITY;
CREATE POLICY rooms_read ON public.game_rooms FOR SELECT TO authenticated USING(true);
CREATE TABLE public.room_members (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.game_rooms(id) ON DELETE CASCADE, seat integer NOT NULL CHECK(seat BETWEEN 0 AND 11), last_seen timestamptz NOT NULL DEFAULT now(), UNIQUE(room_id,seat));
GRANT SELECT ON public.room_members TO authenticated; GRANT ALL ON public.room_members TO service_role;
ALTER TABLE public.room_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_read ON public.room_members FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.in_room(r uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.room_members WHERE room_id=r AND user_id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.in_room(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.in_room(uuid) TO authenticated;
CREATE TABLE public.game_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.game_rooms(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), receiver_id uuid REFERENCES public.profiles(id), text text NOT NULL CHECK(char_length(text) BETWEEN 1 AND 140), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.game_messages TO authenticated; GRANT ALL ON public.game_messages TO service_role;
ALTER TABLE public.game_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.game_messages FOR SELECT TO authenticated USING(public.in_room(room_id) AND (receiver_id IS NULL OR receiver_id=auth.uid() OR sender_id=auth.uid()));
CREATE POLICY messages_send ON public.game_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.in_room(room_id) AND (receiver_id IS NULL OR EXISTS(SELECT 1 FROM public.room_members WHERE user_id=receiver_id AND room_id=game_messages.room_id)));
CREATE TABLE public.game_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, room_id uuid NOT NULL REFERENCES public.game_rooms(id), actor_id uuid NOT NULL REFERENCES public.profiles(id), receiver_id uuid REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN ('gift','gesture')), item_id text NOT NULL, random_seed integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_events TO authenticated; GRANT ALL ON public.game_events TO service_role; GRANT ALL ON SEQUENCE public.game_events_id_seq TO service_role;
ALTER TABLE public.game_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.game_events FOR SELECT TO authenticated USING(public.in_room(room_id));
CREATE TABLE public.user_blocks (user_id uuid NOT NULL REFERENCES public.profiles(id), blocked_id uuid NOT NULL REFERENCES public.profiles(id), PRIMARY KEY(user_id,blocked_id), CHECK(user_id<>blocked_id));
GRANT SELECT,INSERT,DELETE ON public.user_blocks TO authenticated; GRANT ALL ON public.user_blocks TO service_role;
ALTER TABLE public.user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY blocks_own ON public.user_blocks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.user_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES public.profiles(id), reported_id uuid REFERENCES public.profiles(id), message_id uuid REFERENCES public.game_messages(id), reason text NOT NULL DEFAULT 'Şikayet', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.user_reports TO authenticated; GRANT ALL ON public.user_reports TO service_role;
ALTER TABLE public.user_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_own_read ON public.user_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid());
CREATE POLICY reports_own_write ON public.user_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid());
CREATE FUNCTION public.join_game() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; s integer; u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Giriş gerekli'; END IF; PERFORM pg_advisory_xact_lock(749251); DELETE FROM public.room_members WHERE last_seen<now()-interval '90 seconds'; SELECT room_id INTO r FROM public.room_members WHERE user_id=u; IF r IS NOT NULL THEN UPDATE public.room_members SET last_seen=now() WHERE user_id=u; RETURN r; END IF; SELECT g.id INTO r FROM public.game_rooms g WHERE (SELECT count(*) FROM public.room_members m WHERE m.room_id=g.id)<12 ORDER BY g.updated_at DESC LIMIT 1; IF r IS NULL THEN INSERT INTO public.game_rooms DEFAULT VALUES RETURNING id INTO r; END IF; SELECT x INTO s FROM generate_series(0,11) x WHERE NOT EXISTS(SELECT 1 FROM public.room_members WHERE room_id=r AND seat=x) ORDER BY CASE WHEN x=5 THEN 0 ELSE 1 END,x LIMIT 1; INSERT INTO public.room_members(user_id,room_id,seat) VALUES(u,r,s); IF (SELECT round->>'spinner' FROM public.game_rooms WHERE id=r) IS NULL THEN UPDATE public.game_rooms SET round=jsonb_build_object('phase','offer','spinner',u,'target',null,'decisions','{}'::jsonb),updated_at=now() WHERE id=r; END IF; RETURN r; END; $$;
CREATE FUNCTION public.heartbeat_game() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.room_members SET last_seen=now() WHERE user_id=auth.uid(); $$;
CREATE FUNCTION public.leave_game() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ DELETE FROM public.room_members WHERE user_id=auth.uid(); $$;
REVOKE ALL ON FUNCTION public.join_game(),public.heartbeat_game(),public.leave_game() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.join_game(),public.heartbeat_game(),public.leave_game() TO authenticated;
CREATE FUNCTION public.play_round(action text, decision text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; st jsonb; u uuid:=auth.uid(); t uuid; BEGIN SELECT room_id INTO r FROM public.room_members WHERE user_id=u; IF r IS NULL THEN RAISE EXCEPTION 'Masaya katılın'; END IF; SELECT round INTO st FROM public.game_rooms WHERE id=r FOR UPDATE;
IF st->>'phase'='choose' AND (st->>'deadline')::timestamptz<now() THEN st:=jsonb_build_object('phase','offer','spinner',st->>'target','target',null,'decisions','{}'::jsonb); END IF;
IF st->>'phase'='offer' AND NOT EXISTS(SELECT 1 FROM public.room_members WHERE room_id=r AND user_id::text=st->>'spinner' AND last_seen>now()-interval '90 seconds') THEN st:=jsonb_build_object('phase','offer','spinner',u,'target',null,'decisions','{}'::jsonb); END IF;
IF action='spin' THEN IF st->>'phase'<>'offer' OR st->>'spinner'<>u::text THEN RAISE EXCEPTION 'Sıra başka oyuncuda'; END IF; SELECT user_id INTO t FROM public.room_members WHERE room_id=r AND user_id<>u AND last_seen>now()-interval '90 seconds' ORDER BY random() LIMIT 1; IF t IS NULL THEN RAISE EXCEPTION 'Başka bir oyuncu bekleniyor'; END IF; st:=jsonb_build_object('phase','choose','spinner',u,'target',t,'decisions','{}'::jsonb,'deadline',now()+interval '20 seconds','started_at',now());
ELSIF action='decide' THEN IF decision NOT IN ('kiss','refuse') OR st->>'phase'<>'choose' OR u::text NOT IN (st->>'spinner',st->>'target') THEN RAISE EXCEPTION 'Geçersiz karar'; END IF; IF (st->'decisions')?u::text THEN RAISE EXCEPTION 'Karar zaten gönderildi'; END IF; st:=jsonb_set(st,ARRAY['decisions',u::text],to_jsonb(decision)); IF (st->'decisions')?(st->>'spinner') AND (st->'decisions')?(st->>'target') THEN IF st->'decisions'->>(st->>'spinner')='kiss' AND st->'decisions'->>(st->>'target')='kiss' THEN UPDATE public.wallets SET kisses=kisses+1,hearts=hearts+1 WHERE user_id::text IN (st->>'spinner',st->>'target'); END IF; st:=jsonb_set(st,'{phase}','"result"'); st:=jsonb_set(st,'{deadline}',to_jsonb(now()+interval '3 seconds')); END IF;
ELSIF action='refresh' THEN IF st->>'phase'='result' AND (st->>'deadline')::timestamptz<now() THEN st:=jsonb_build_object('phase','offer','spinner',st->>'target','target',null,'decisions','{}'::jsonb); END IF;
ELSE RAISE EXCEPTION 'Geçersiz işlem'; END IF; UPDATE public.game_rooms SET round=st,updated_at=now() WHERE id=r; RETURN st; END; $$;
REVOKE ALL ON FUNCTION public.play_round(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.play_round(text,text) TO authenticated;
CREATE FUNCTION public.purchase_game_item(actor uuid, receiver uuid, kind text, item text, price bigint, need_kisses bigint, need_vip boolean, seed integer) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; w public.wallets; eid bigint; BEGIN IF price<0 OR kind NOT IN ('gift','gesture') THEN RAISE EXCEPTION 'Geçersiz ürün'; END IF; SELECT room_id INTO r FROM public.room_members WHERE user_id=actor AND last_seen>now()-interval '90 seconds'; IF r IS NULL THEN RAISE EXCEPTION 'Masaya katılın'; END IF; IF kind='gift' AND NOT EXISTS(SELECT 1 FROM public.room_members WHERE user_id=receiver AND room_id=r) THEN RAISE EXCEPTION 'Oyuncu masada değil'; END IF; SELECT * INTO w FROM public.wallets WHERE user_id=actor FOR UPDATE; IF w.tokens<price THEN RAISE EXCEPTION 'Yeterli jeton yok'; END IF; IF w.kisses<need_kisses OR (need_vip AND NOT w.vip) THEN RAISE EXCEPTION 'Bu ürün kilitli'; END IF; UPDATE public.wallets SET tokens=tokens-price,gestures=gestures+CASE WHEN kind='gesture' THEN 1 ELSE 0 END WHERE user_id=actor; INSERT INTO public.game_events(room_id,actor_id,receiver_id,kind,item_id,random_seed) VALUES(r,actor,receiver,kind,item,seed) RETURNING id INTO eid; RETURN eid; END; $$;
REVOKE ALL ON FUNCTION public.purchase_game_item(uuid,uuid,text,text,bigint,bigint,boolean,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.purchase_game_item(uuid,uuid,text,text,bigint,bigint,boolean,integer) TO service_role;
CREATE INDEX messages_room_time ON public.game_messages(room_id,created_at); CREATE INDEX events_room_id ON public.game_events(room_id,id);
ALTER PUBLICATION supabase_realtime ADD TABLE public.room_members,public.game_rooms,public.game_messages,public.game_events,public.wallets,public.profiles;

-- ---------- 0001_validate_player_signup.sql ----------
CREATE OR REPLACE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE handle text; BEGIN handle:=lower(coalesce(nullif(NEW.raw_user_meta_data->>'username',''),'u_'||left(replace(NEW.id::text,'-',''),24))); IF handle !~ '^[a-z0-9_]{3,30}$' THEN RAISE EXCEPTION 'Kullanıcı adı 3–30 harf, rakam veya alt çizgi olmalı'; END IF; INSERT INTO public.profiles(id,username,display_name) VALUES(NEW.id,handle,left(coalesce(nullif(NEW.raw_user_meta_data->>'display_name',''),nullif(NEW.raw_user_meta_data->>'full_name',''),'Oyuncu'),40)); INSERT INTO public.wallets(user_id) VALUES(NEW.id); RETURN NEW; END; $$;

-- ---------- 0002_restrict_game_rpc_anonymous_access.sql ----------
REVOKE ALL ON FUNCTION public.create_player_profile() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.in_room(uuid),public.join_game(),public.heartbeat_game(),public.leave_game(),public.play_round(text,text) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.purchase_game_item(uuid,uuid,text,text,bigint,bigint,boolean,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.in_room(uuid),public.join_game(),public.heartbeat_game(),public.leave_game(),public.play_round(text,text) TO authenticated;
CREATE FUNCTION public.player_stats(player uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('kisses',kisses,'gestures',gestures,'hearts',hearts) FROM public.wallets WHERE user_id=player AND auth.uid() IS NOT NULL; $$;
REVOKE ALL ON FUNCTION public.player_stats(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.player_stats(uuid) TO authenticated;

-- ---------- 0003_recover_room_turns_and_secure_avatars.sql ----------
CREATE OR REPLACE FUNCTION public.join_game() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; s integer; u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Giriş gerekli'; END IF; PERFORM pg_advisory_xact_lock(749251); DELETE FROM public.room_members WHERE last_seen<now()-interval '90 seconds'; SELECT room_id INTO r FROM public.room_members WHERE user_id=u; IF r IS NULL THEN SELECT g.id INTO r FROM public.game_rooms g WHERE (SELECT count(*) FROM public.room_members m WHERE m.room_id=g.id)<12 ORDER BY g.updated_at DESC LIMIT 1; IF r IS NULL THEN INSERT INTO public.game_rooms DEFAULT VALUES RETURNING id INTO r; END IF; SELECT x INTO s FROM generate_series(0,11) x WHERE NOT EXISTS(SELECT 1 FROM public.room_members WHERE room_id=r AND seat=x) ORDER BY CASE WHEN x=5 THEN 0 ELSE 1 END,x LIMIT 1; INSERT INTO public.room_members(user_id,room_id,seat) VALUES(u,r,s); ELSE UPDATE public.room_members SET last_seen=now() WHERE user_id=u; END IF; IF NOT EXISTS(SELECT 1 FROM public.room_members m JOIN public.game_rooms g ON g.id=m.room_id WHERE m.room_id=r AND m.user_id::text=g.round->>'spinner') THEN UPDATE public.game_rooms SET round=jsonb_build_object('phase','offer','spinner',u,'target',null,'decisions','{}'::jsonb),updated_at=now() WHERE id=r; END IF; RETURN r; END; $$;
CREATE OR REPLACE FUNCTION public.purchase_game_item(actor uuid, receiver uuid, kind text, item text, price bigint, need_kisses bigint, need_vip boolean, seed integer) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; w public.wallets; eid bigint; BEGIN IF price<0 OR kind NOT IN ('gift','gesture') THEN RAISE EXCEPTION 'Geçersiz ürün'; END IF; SELECT room_id INTO r FROM public.room_members WHERE user_id=actor AND last_seen>now()-interval '90 seconds'; IF r IS NULL THEN RAISE EXCEPTION 'Masaya katılın'; END IF; IF kind='gift' AND NOT EXISTS(SELECT 1 FROM public.room_members WHERE user_id=receiver AND room_id=r) THEN RAISE EXCEPTION 'Oyuncu masada değil'; END IF; SELECT * INTO w FROM public.wallets WHERE user_id=actor FOR UPDATE; IF (kind='gift' AND w.hearts<price) OR (kind='gesture' AND w.tokens<price) THEN RAISE EXCEPTION 'Yeterli bakiye yok'; END IF; IF w.kisses<need_kisses OR (need_vip AND NOT w.vip) THEN RAISE EXCEPTION 'Bu ürün kilitli'; END IF; UPDATE public.wallets SET hearts=hearts-CASE WHEN kind='gift' THEN price ELSE 0 END,tokens=tokens-CASE WHEN kind='gesture' THEN price ELSE 0 END,gestures=gestures+CASE WHEN kind='gesture' THEN 1 ELSE 0 END WHERE user_id=actor; INSERT INTO public.game_events(room_id,actor_id,receiver_id,kind,item_id,random_seed) VALUES(r,actor,receiver,kind,item,seed) RETURNING id INTO eid; RETURN eid; END; $$;
CREATE POLICY avatars_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='avatars');
CREATE POLICY avatars_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY avatars_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
ALTER TABLE public.profiles ADD COLUMN avatar_path text NOT NULL DEFAULT '';
GRANT UPDATE(avatar_path) ON public.profiles TO authenticated;
CREATE TABLE public.player_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE ON public.player_preferences TO authenticated; GRANT ALL ON public.player_preferences TO service_role;
ALTER TABLE public.player_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY preferences_own ON public.player_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());

-- ---------- 0004_synchronize_round_timing_and_blocked_chat.sql ----------
ALTER POLICY messages_read ON public.game_messages USING(public.in_room(room_id) AND (receiver_id IS NULL OR receiver_id=auth.uid() OR sender_id=auth.uid()) AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE b.user_id=auth.uid() AND b.blocked_id=sender_id));
CREATE OR REPLACE FUNCTION public.play_round(action text, decision text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; st jsonb; u uuid:=auth.uid(); t uuid; BEGIN SELECT room_id INTO r FROM public.room_members WHERE user_id=u AND last_seen>now()-interval '90 seconds'; IF r IS NULL THEN RAISE EXCEPTION 'Masaya katılın'; END IF; SELECT round INTO st FROM public.game_rooms WHERE id=r FOR UPDATE;
IF st->>'phase' IN ('choose','result') AND (st->>'deadline')::timestamptz<now() THEN st:=jsonb_build_object('phase','offer','spinner',st->>'target','target',null,'decisions','{}'::jsonb); END IF;
IF st->>'phase'='offer' AND NOT EXISTS(SELECT 1 FROM public.room_members WHERE room_id=r AND user_id::text=st->>'spinner' AND last_seen>now()-interval '90 seconds') THEN st:=jsonb_build_object('phase','offer','spinner',u,'target',null,'decisions','{}'::jsonb); END IF;
IF action='spin' THEN IF st->>'phase'<>'offer' OR st->>'spinner'<>u::text THEN RAISE EXCEPTION 'Sıra başka oyuncuda'; END IF; SELECT user_id INTO t FROM public.room_members WHERE room_id=r AND user_id<>u AND last_seen>now()-interval '90 seconds' ORDER BY random() LIMIT 1; IF t IS NULL THEN RAISE EXCEPTION 'Başka bir oyuncu bekleniyor'; END IF; st:=jsonb_build_object('phase','choose','spinner',u,'target',t,'decisions','{}'::jsonb,'deadline',now()+interval '15 seconds','started_at',now(),'turns',5+floor(random()*11)::integer);
ELSIF action='decide' THEN IF decision IS NULL OR decision NOT IN ('kiss','refuse') OR st->>'phase'<>'choose' OR u::text NOT IN (st->>'spinner',st->>'target') THEN RAISE EXCEPTION 'Geçersiz karar'; END IF; IF now()<(st->>'started_at')::timestamptz+interval '6 seconds' THEN RAISE EXCEPTION 'Şişenin durmasını bekleyin'; END IF; IF (st->'decisions')?u::text THEN RAISE EXCEPTION 'Karar zaten gönderildi'; END IF; st:=jsonb_set(st,ARRAY['decisions',u::text],to_jsonb(decision)); IF (st->'decisions')?(st->>'spinner') AND (st->'decisions')?(st->>'target') THEN IF st->'decisions'->>(st->>'spinner')='kiss' AND st->'decisions'->>(st->>'target')='kiss' THEN UPDATE public.wallets SET kisses=kisses+1,hearts=hearts+1 WHERE user_id::text IN (st->>'spinner',st->>'target'); END IF; st:=jsonb_set(st,'{phase}','"result"'); st:=jsonb_set(st,'{deadline}',to_jsonb(now()+interval '3 seconds')); END IF;
ELSIF action<>'refresh' OR action IS NULL THEN RAISE EXCEPTION 'Geçersiz işlem'; END IF;
UPDATE public.game_rooms SET round=st,updated_at=now() WHERE id=r AND round IS DISTINCT FROM st; RETURN st; END; $$;
CREATE OR REPLACE FUNCTION public.heartbeat_game() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.room_members SET last_seen=now() WHERE user_id=auth.uid(); IF FOUND THEN PERFORM public.play_round('refresh'); END IF; END; $$;
CREATE INDEX game_messages_room_time_idx ON public.game_messages(room_id,created_at DESC);
CREATE INDEX game_events_room_id_idx ON public.game_events(room_id,id DESC);
CREATE INDEX room_members_room_seen_idx ON public.room_members(room_id,last_seen);

-- ---------- 0005_player_onboarding_and_mixed_gender_rounds.sql ----------
ALTER TABLE public.profiles ADD COLUMN player_id bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE;
ALTER TABLE public.profiles ADD COLUMN gender text;
ALTER TABLE public.profiles ADD COLUMN age integer;
ALTER TABLE public.profiles ADD COLUMN onboarding_completed_at timestamptz;
ALTER TABLE public.profiles ADD CONSTRAINT profile_gender_valid CHECK (gender IS NULL OR gender IN ('male','female'));
ALTER TABLE public.profiles ADD CONSTRAINT profile_age_valid CHECK (age IS NULL OR age BETWEEN 18 AND 99);
CREATE OR REPLACE FUNCTION public.complete_player_onboarding(selected_gender text, selected_age integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Giriş gerekli'; END IF; IF selected_gender IS NULL OR selected_gender NOT IN ('male','female') OR selected_age IS NULL OR selected_age NOT BETWEEN 18 AND 99 THEN RAISE EXCEPTION 'Cinsiyet ve yaş seçin (18–99)'; END IF; UPDATE public.profiles SET gender=selected_gender,age=selected_age,onboarding_completed_at=now() WHERE id=auth.uid() AND onboarding_completed_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Profil seçimi zaten tamamlandı'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.complete_player_onboarding(text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.complete_player_onboarding(text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.play_round(action text, decision text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; st jsonb; u uuid:=auth.uid(); t uuid; g text; eligible boolean; BEGIN SELECT room_id INTO r FROM public.room_members WHERE user_id=u AND last_seen>now()-interval '90 seconds'; IF r IS NULL THEN RAISE EXCEPTION 'Masaya katılın'; END IF; SELECT round INTO st FROM public.game_rooms WHERE id=r FOR UPDATE;
SELECT EXISTS(SELECT 1 FROM public.room_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.room_id=r AND m.last_seen>now()-interval '90 seconds' AND p.gender='male' AND p.onboarding_completed_at IS NOT NULL) AND EXISTS(SELECT 1 FROM public.room_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.room_id=r AND m.last_seen>now()-interval '90 seconds' AND p.gender='female' AND p.onboarding_completed_at IS NOT NULL) INTO eligible;
IF NOT eligible THEN st:=jsonb_build_object('phase','waiting','spinner',null,'target',null,'decisions','{}'::jsonb);
ELSE
IF st->>'phase'='waiting' OR st->>'phase' IN ('choose','result') AND (st->>'deadline')::timestamptz<now() THEN st:=jsonb_build_object('phase','offer','spinner',st->>'target','target',null,'decisions','{}'::jsonb); END IF;
IF st->>'phase'='offer' AND NOT EXISTS(SELECT 1 FROM public.room_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.room_id=r AND m.user_id::text=st->>'spinner' AND m.last_seen>now()-interval '90 seconds' AND p.onboarding_completed_at IS NOT NULL) THEN SELECT m.user_id INTO t FROM public.room_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.room_id=r AND m.last_seen>now()-interval '90 seconds' AND p.onboarding_completed_at IS NOT NULL ORDER BY m.seat LIMIT 1; st:=jsonb_build_object('phase','offer','spinner',t,'target',null,'decisions','{}'::jsonb); END IF;
END IF;
IF action='spin' THEN IF NOT eligible THEN RAISE EXCEPTION 'En az bir kız ve bir erkek oyuncu bekleniyor'; END IF; IF st->>'phase'<>'offer' OR st->>'spinner' IS DISTINCT FROM u::text THEN RAISE EXCEPTION 'Sıra başka oyuncuda'; END IF; SELECT gender INTO g FROM public.profiles WHERE id=u AND onboarding_completed_at IS NOT NULL; SELECT m.user_id INTO t FROM public.room_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.room_id=r AND m.user_id<>u AND m.last_seen>now()-interval '90 seconds' AND p.onboarding_completed_at IS NOT NULL AND p.gender<>g ORDER BY random() LIMIT 1; IF t IS NULL THEN RAISE EXCEPTION 'Karşı cinsiyetten oyuncu bekleniyor'; END IF; st:=jsonb_build_object('phase','choose','spinner',u,'target',t,'decisions','{}'::jsonb,'deadline',now()+interval '15 seconds','started_at',now(),'turns',5+floor(random()*11)::integer);
ELSIF action='decide' THEN IF decision IS NULL OR decision NOT IN ('kiss','refuse') OR st->>'phase'<>'choose' OR u::text NOT IN (st->>'spinner',st->>'target') THEN RAISE EXCEPTION 'Geçersiz karar'; END IF; IF now()<(st->>'started_at')::timestamptz+interval '6 seconds' THEN RAISE EXCEPTION 'Şişenin durmasını bekleyin'; END IF; IF (st->'decisions')?u::text THEN RAISE EXCEPTION 'Karar zaten gönderildi'; END IF; st:=jsonb_set(st,ARRAY['decisions',u::text],to_jsonb(decision)); IF (st->'decisions')?(st->>'spinner') AND (st->'decisions')?(st->>'target') THEN IF st->'decisions'->>(st->>'spinner')='kiss' AND st->'decisions'->>(st->>'target')='kiss' THEN UPDATE public.wallets SET kisses=kisses+1,hearts=hearts+1 WHERE user_id::text IN (st->>'spinner',st->>'target'); END IF; st:=jsonb_set(st,'{phase}','"result"'); st:=jsonb_set(st,'{deadline}',to_jsonb(now()+interval '3 seconds')); END IF;
ELSIF action<>'refresh' OR action IS NULL THEN RAISE EXCEPTION 'Geçersiz işlem'; END IF;
UPDATE public.game_rooms SET round=st,updated_at=now() WHERE id=r AND round IS DISTINCT FROM st; RETURN st; END; $$;
REVOKE ALL ON FUNCTION public.play_round(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.play_round(text,text) TO authenticated;

-- ---------- 0006_initial_heart_balance.sql ----------
ALTER TABLE public.wallets ALTER COLUMN hearts SET DEFAULT 10000;

-- ---------- 0007_change_room_transaction.sql ----------
CREATE OR REPLACE FUNCTION public.change_game_room() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_room uuid; r uuid; s integer; u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Giriş gerekli'; END IF; PERFORM pg_advisory_xact_lock(749251); SELECT room_id INTO old_room FROM public.room_members WHERE user_id=u; DELETE FROM public.room_members WHERE user_id=u OR last_seen<now()-interval '90 seconds'; SELECT g.id INTO r FROM public.game_rooms g WHERE g.id IS DISTINCT FROM old_room AND (SELECT count(*) FROM public.room_members m WHERE m.room_id=g.id)<12 ORDER BY g.updated_at DESC LIMIT 1; IF r IS NULL THEN INSERT INTO public.game_rooms DEFAULT VALUES RETURNING id INTO r; END IF; SELECT x INTO s FROM generate_series(0,11) x WHERE NOT EXISTS(SELECT 1 FROM public.room_members WHERE room_id=r AND seat=x) ORDER BY CASE WHEN x=5 THEN 0 ELSE 1 END,x LIMIT 1; INSERT INTO public.room_members(user_id,room_id,seat) VALUES(u,r,s); PERFORM public.play_round('refresh'); RETURN r; END; $$; REVOKE ALL ON FUNCTION public.change_game_room() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.change_game_room() TO authenticated;

